package com.bank.convert;

import org.springframework.stereotype.Service;
import java.util.stream.Collectors;

@Service
public class UpperCaseService {

    // Stream approach (interview answer):
    public String toUpperCaseStream(String input) {
        return input.chars()                           // IntStream of char codes
            .map(Character::toUpperCase)                // uppercase each char code
            .mapToObj(c -> String.valueOf((char) c))   // int → String
            .collect(Collectors.joining());              // join all chars
    }

    // Practical approach (production code):
    public String toUpperCasePractical(String input) {
        return input.toUpperCase();  // one method call — always prefer this!
    }
}
