package com.bank.convert;

import org.junit.jupiter.api.Test;
import java.util.stream.Collectors;
import static org.assertj.core.api.Assertions.*;

class UpperCaseTest {

    @Test void basic() {
        String result = "neft transfer".chars()
            .map(Character::toUpperCase)
            .mapToObj(c -> String.valueOf((char) c))
            .collect(Collectors.joining());
        assertThat(result).isEqualTo("NEFT TRANSFER");
    }

    @Test void alreadyUpperCase() {
        String result = "RELIANCE".chars()
            .map(Character::toUpperCase)
            .mapToObj(c -> String.valueOf((char) c))
            .collect(Collectors.joining());
        assertThat(result).isEqualTo("RELIANCE");
    }

    @Test void mixedCase() {
        String result = "Rajesh Kumar".chars()
            .map(Character::toUpperCase)
            .mapToObj(c -> String.valueOf((char) c))
            .collect(Collectors.joining());
        assertThat(result).isEqualTo("RAJESH KUMAR");
    }

    @Test void emptyString() {
        assertThat("".chars().map(Character::toUpperCase)
            .mapToObj(c -> String.valueOf((char) c))
            .collect(Collectors.joining())).isEmpty();
    }
}
