package com.bank.java8;

import org.junit.jupiter.api.Test;
import java.util.List;
import static org.assertj.core.api.Assertions.assertThat;

class UppercaseStreamTest {

    @Test
    void mapToUpperCaseKeepsSourceIntact() {
        List<String> holders = List.of("rajesh", "priya");

        List<String> upper = holders.stream()
            .map(String::toUpperCase)
            .toList();

        assertThat(upper).containsExactly("RAJESH", "PRIYA");
        assertThat(holders).containsExactly("rajesh", "priya"); // unchanged
    }
}
